using System.Globalization;
using ValveResourceFormat.Blocks;
using ValveResourceFormat;
using ValveResourceFormat.ResourceTypes;
using ValveKeyValue;
// The template contains only animation blocks and DATA for skeleton validation.
// Never copy template DATA, meshes, materials, physics or external references.
// Both arcana styles share the skeleton; their authored visuals remain in host.
internal static class WindrunnerFocusFire {
 static string S(KVObject v)=>v.ToString(CultureInfo.InvariantCulture);
 static double[] N(KVObject v)=>v.Values.Select(x=>x.ToDouble(CultureInfo.InvariantCulture)).ToArray();
 private sealed record Request(string Input,string Output,string Template);
 public static void Run(string manifest){var q=System.Text.Json.JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new System.Text.Json.JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Invalid Focus Fire request");Transfer(q.Input,q.Template,q.Output);}
 public static void Transfer(string input,string reference,string output){
 var bytes=File.ReadAllBytes(input);var source=File.ReadAllBytes(reference);using var host=new Resource{FileName=input};using var donor=new Resource{FileName=reference};host.Read(input);donor.Read(reference);var model=(Model)host.DataBlock!;var sourceModel=(Model)donor.DataBlock!;var a=model.Data["m_modelSkeleton"];var b=sourceModel.Data["m_modelSkeleton"];var names=a["m_boneName"].Values.Select(S).ToArray();var sourceNames=b["m_boneName"].Values.Select(S).ToArray();if(names.Length!=205||sourceNames.Length!=205)throw new Exception("Unexpected Windranger skeleton profiles");foreach(var (name,i)in names.Select((n,i)=>(n,i))){int j=Array.IndexOf(sourceNames,name);if(j<0)throw new Exception("Host bone missing in animation source "+name);int pa=a["m_nParent"].Values.ElementAt(i).ToInt32(CultureInfo.InvariantCulture),pb=b["m_nParent"].Values.ElementAt(j).ToInt32(CultureInfo.InvariantCulture);if((pa<0?"":names[pa])!=(pb<0?"":sourceNames[pb]))throw new Exception("Bone parent mismatch "+name);foreach(var key in new[]{"m_bonePosParent","m_boneRotParent","m_boneScaleParent"}){if(!a.TryGetValue(key,out var av)||!b.TryGetValue(key,out var bv))continue;var x=av.Values.ElementAt(i);var y=bv.Values.ElementAt(j);var xx=x.IsArray?N(x):new[]{x.ToDouble(CultureInfo.InvariantCulture)};var yy=y.IsArray?N(y):new[]{y.ToDouble(CultureInfo.InvariantCulture)};bool same=xx.Length==yy.Length&&xx.Zip(yy).All(p=>Math.Abs(p.First-p.Second)<.001);bool opposite=xx.Length==yy.Length&&key=="m_boneRotParent"&&xx.Zip(yy).All(p=>Math.Abs(p.First+p.Second)<.001);if(!same&&!opposite)throw new Exception("Bind transform mismatch "+name+" / "+key);}}
 var missing=(donor.ExternalReferences?.ResourceRefInfoList??[]).Where(v=>(v.Name.EndsWith(".vpcf")||v.Name.EndsWith(".vsnd"))&&!(host.ExternalReferences?.ResourceRefInfoList.Any(h=>h.Id==v.Id)??false)).ToArray();foreach(var item in missing){var token=BitConverter.GetBytes(item.Id);void Check(KVObject value){if(value.IsCollection){foreach(var pair in value.Children)Check(pair.Value);}else if(value.IsArray){foreach(var child in value.Values)Check(child);}else if(value.ValueType==KVValueType.String&&S(value).Contains(item.Name,StringComparison.Ordinal))throw new Exception("Missing animation event resource "+item.Name);else if(value.ValueType==KVValueType.UInt64&&value.ToUInt64(CultureInfo.InvariantCulture)==item.Id)throw new Exception("Missing animation event ID "+item.Name);else if(value.ValueType==KVValueType.BinaryBlob&&value.AsBlob().AsSpan().IndexOf(token)>=0)throw new Exception("Missing embedded event ID "+item.Name);}foreach(var bl in donor.Blocks.Where(v=>v.Type.ToString()is "ANIM" or "ASEQ" or "AGRP"))Check(Read(donor,source,bl).Data.Root);Console.WriteLine("Source-only reference not used by animation metadata/blobs: "+item.Name);}var kinds=new[]{"ANIM","AGRP","ASEQ"};var chunks=host.Blocks.Select(bl=>(bl.Type,bytes.AsSpan((int)bl.Offset,(int)bl.Size).ToArray())).ToList();foreach(var kind in kinds){var target=host.Blocks.Single(bl=>bl.Type.ToString()==kind);var from=donor.Blocks.Single(bl=>bl.Type.ToString()==kind);chunks[host.Blocks.IndexOf(target)]=(target.Type,source.AsSpan((int)from.Offset,(int)from.Size).ToArray());}Write(bytes,chunks,output);
 using var result=new Resource{FileName=output};result.Read(output);var written=File.ReadAllBytes(output);for(int i=0;i<host.Blocks.Count;i++){var old=host.Blocks[i];var next=result.Blocks[i];if(old.Type!=next.Type)throw new Exception("Block order changed");if(!kinds.Contains(old.Type.ToString())&&!bytes.AsSpan((int)old.Offset,(int)old.Size).SequenceEqual(written.AsSpan((int)next.Offset,(int)next.Size)))throw new Exception("Geometry/material/physics block changed "+old.Type);}
 Console.WriteLine("205 host bones validated against source bind transforms and parents; only ANIM/AGRP/ASEQ replaced; own geometry, skeleton, materials, PHYS and references preserved");

 }
 static ValveResourceFormat.ResourceTypes.BinaryKV3 Read(Resource r,byte[] bytes,Block b){var kv=new ValveResourceFormat.ResourceTypes.BinaryKV3(b.Type){Resource=r,Offset=b.Offset,Size=b.Size};using var reader=new BinaryReader(new MemoryStream(bytes));reader.BaseStream.Position=b.Offset;kv.Read(reader);return kv;}

 static void Write(byte[] bytes,List<(BlockType Type,byte[] Bytes)> chunks,string output){
 using var stream=File.Create(output);using var w=new BinaryWriter(stream);w.Write(0u);w.Write(bytes.AsSpan(4,4));w.Write(8u);w.Write((uint)chunks.Count);w.Write(new byte[chunks.Count*12]);
 for(int i=0;i<chunks.Count;i++){w.Write(new byte[(16-stream.Position%16)%16]);long start=stream.Position;w.Write(chunks[i].Bytes);long end=stream.Position;stream.Position=16+i*12;w.Write((uint)chunks[i].Type);w.Write((uint)(start-stream.Position));w.Write((uint)chunks[i].Bytes.Length);stream.Position=end;}stream.Position=0;w.Write((uint)stream.Length);
 }
}
